ALTER TABLE "WhatsAppIntegration" ADD COLUMN "metaAppSecret" TEXT, ADD COLUMN "verifyTokenHash" TEXT, ADD COLUMN "webhookVerifiedAt" TIMESTAMP(3), ADD COLUMN "webhookLastReceivedAt" TIMESTAMP(3);
ALTER TABLE "AutomationJob" ADD COLUMN "claimedAt" TIMESTAMP(3), ADD COLUMN "retryable" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "MerchantNotification" ("id" TEXT PRIMARY KEY,"merchantId" TEXT NOT NULL REFERENCES "Merchant"("id") ON DELETE CASCADE ON UPDATE CASCADE,"key" TEXT NOT NULL,"severity" TEXT NOT NULL,"title" TEXT NOT NULL,"detail" TEXT NOT NULL,"action" TEXT NOT NULL,"readAt" TIMESTAMP(3),"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "MerchantNotification_merchantId_key_key" ON "MerchantNotification"("merchantId","key");
CREATE INDEX "MerchantNotification_merchantId_resolvedAt_createdAt_idx" ON "MerchantNotification"("merchantId","resolvedAt","createdAt");
CREATE TABLE "InboxEvent" ("id" TEXT PRIMARY KEY,"merchantId" TEXT NOT NULL REFERENCES "Merchant"("id") ON DELETE CASCADE ON UPDATE CASCADE,"provider" TEXT NOT NULL,"eventId" TEXT NOT NULL,"topic" TEXT NOT NULL,"payload" JSONB NOT NULL,"state" TEXT NOT NULL DEFAULT 'QUEUED',"attempts" INTEGER NOT NULL DEFAULT 0,"dueAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"leaseToken" TEXT,"leaseUntil" TIMESTAMP(3),"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" TIMESTAMP(3));
CREATE UNIQUE INDEX "InboxEvent_merchantId_provider_eventId_key" ON "InboxEvent"("merchantId","provider","eventId");
CREATE INDEX "InboxEvent_state_dueAt_idx" ON "InboxEvent"("state","dueAt");
CREATE INDEX "InboxEvent_merchantId_createdAt_idx" ON "InboxEvent"("merchantId","createdAt");
CREATE TABLE "ShopifySyncState" ("merchantId" TEXT PRIMARY KEY REFERENCES "Merchant"("id") ON DELETE CASCADE ON UPDATE CASCADE,"checkpoint" TIMESTAMP(3),"windowStart" TIMESTAMP(3),"windowEnd" TIMESTAMP(3),"cursor" TEXT,"leaseToken" TEXT,"leaseUntil" TIMESTAMP(3),"nextRunAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSuccessAt" TIMESTAMP(3),"error" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0);
